/** set id -> the manifest rows in that set, in round-robin order. */
export const SETS = MANIFEST.reduce((m, e) => {
  (m[e.set] || (m[e.set] = [])).push(e);
  return m;
}, /** @type {Record<string, typeof MANIFEST>} */({}));

